{
  "description": "A single quadrupedal creature is shown in right-facing profile standing on flat ground against a plain off-white background. The animal has a low, stout body with an arched back and a long tapering tail extending to the left. The head, underside, and limbs are pale gray with slightly pinkish and bluish tones, smooth and wrinkled skin, and small dark speckles on the head. Behind the head on the neck are six pink feathery external gills. The entire dorsal surface from the back of the neck to the tip of the tail is covered in overlapping large brown and dark gray scales. The creature stands on four short thick limbs with clawed feet, and its belly shows pale transverse wrinkling. The overall appearance combines amphibian-like head and limbs with a scaled armored back and tail.",
  "parts": [
    {
      "part": "head",
      "looks_like": "broad, flat and blunt-snouted with a pale gray skin covered in small dark speckles, large round eyes with dark pupils and light blue-gray irises on the sides, small round nostrils at the tip of the snout, and a slightly upturned mouth",
      "where": "at the front right end of the body, facing right"
    },
    {
      "part": "gills",
      "looks_like": "six pink feathery external gills with many fine filamentous branches, three on each side, each on a pale fleshy stalk",
      "where": "protruding outward from the sides of the neck immediately behind the head"
    },
    {
      "part": "legs",
      "looks_like": "four short, thick, stout limbs with pale gray wrinkled skin, muscular and splayed outward to support the low body",
      "where": "two forelimbs under the chest and two hindlimbs under the rear body, with the left hindlimb partially obscured behind the right hindlimb"
    },
    {
      "part": "feet",
      "looks_like": "four broad feet with five slender digits each tipped with small dark claws, pale gray with visible skin texture",
      "where": "at the ends of the four legs resting on the ground"
    },
    {
      "part": "tail",
      "looks_like": "long, thick at the base and tapering to a point, covered dorsally in overlapping scales with a paler smooth underside visible near the base",
      "where": "extending to the left from the rear of the body"
    },
    {
      "part": "scales",
      "looks_like": "large overlapping keratinous scales in shades of dark brown to gray-brown with lighter edges and fine striations, arranged in diagonal rows",
      "where": "covering the entire dorsal surface from behind the gills over the arched back and along the full length of the tail"
    },
    {
      "part": "markings",
      "looks_like": "small dark gray speckles scattered on the head and faint transverse wrinkles and pale segmentation on the belly and throat",
      "where": "speckles on the dorsal and lateral head, wrinkled banding on the pale ventral side between the front and hind legs"
    }
  ],
  "attached_objects": [],
  "animals": [
    "axolotl",
    "pangolin"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
